WITH -- Get all individual interactions with timestamps LinkMessageTimestamps AS ( SELECT m.link_id, mr.contact_id AS contact_address_id, m.internal_date_ts FROM email_messages m JOIN email_message_recipients mr ON m.id = mr.message_id WHERE m.link_id = $1 AND m.is_sent = TRUE AND mr.contact_id IS NOT NULL ), -- Get the latest interaction timestamp for each contact_address_id LatestContactInteractions AS ( SELECT lmt.link_id, lmt.contact_address_id, MAX(lmt.internal_date_ts) AS last_interaction_ts FROM LinkMessageTimestamps lmt WHERE lmt.contact_address_id IS NOT NULL GROUP BY lmt.link_id, lmt.contact_address_id ) -- Final SELECT to join with email_addresses and get details SELECT c.email_address as "email_address!", c.name as "name?", c.sfs_photo_url as "photo_url?", lci.last_interaction_ts as "last_interaction!" FROM LatestContactInteractions lci JOIN email_contacts c ON lci.contact_address_id = c.id ORDER BY lci.last_interaction_ts DESC, c.email_address
